output_text:
{
  "decline_reason": "",
  "claims": [
    {
      "text": "The Manual identifies specific court appeal rights, rather than a general right to appeal every Registrar decision, to the Federal Court or the Federal Circuit and Family Court of Australia (Division 2).",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~1",
          "quote": "The Federal Court and the Federal Circuit and Family Court of Australia (Division 2) have jurisdiction to hear and determine appeals against decisions, directions or orders of the Registrar (sections 191 and 191A). The statutory rights of appeal to the courts are specifically set out in the relevant sections of the Trade Marks Act 1995"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For domestic applications and registrations, the Manual lists appeals concerning rejection or conditional acceptance, registration opposition decisions, amendment requests, revocation under section 84A, and opposed removal applications.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~1",
          "quote": "Appeals from the Registrar’s decisions may be made to the Federal Court or the Federal Circuit and Family Court of Australia (Division 2) in respect of: the rejection of an application, or the decision to accept it subject to conditions or limitations (section 35), a decision in an opposition matter to register a trade mark, with or without conditions or limitations, or to refuse it (section 56), a decision on a request for amendment of the application to register a trade mark or of another document (section 67), a decision on a request to amend the particulars of a trade mark entered in the Register (secton 83), a decision on a request to amend the particulars of a trade mark entered in the Register to achieve consistency with international agreements (section 83A), a decision to revoke registration under section 84A (section 84D), a decision in an opposed removal application (section 104)"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For international registrations designating Australia, the Manual lists appeals concerning rejection or conditional acceptance, opposition to extension of protection, and decisions whether to exercise powers to amend or cease protection, including for non-use.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~1",
          "quote": "the rejection of an IRDA, or the decision to accept it subject to conditions or limitations (reg 17A.26), a decision in an opposition matter to refuse or extend protection to an International Registration Designating Australia (reg 17A.34P) a decision to exercise or not exercise a power to amend or cease protection of a protected international trade mark (reg 17A.42A) a decision to exercise or not exercise a power to amend or cease protection of a protected international trade mark for non-use (reg 17A.48D and 17A.48X)"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "These appeal categories are reported from the Manual, not independently verified against the relevant legislation supplied here; the Manual also cites regulation 17A.42F in its introductory list but regulation 17A.42A in its detailed description, so the applicable provision is uncertain on these materials.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~1",
          "quote": "the Trade Mark Regulations viz. reg 17A.26, 17A.34P, 17A.42F."
        },
        {
          "ref": "TMM/Part52/5/5/1~1",
          "quote": "a decision to exercise or not exercise a power to amend or cease protection of a protected international trade mark (reg 17A.42A)"
        }
      ],
      "authority": "none"
    },
    {
      "text": "The Manual describes a statutory court appeal as a complete re-decision on the material before the court, in the nature of a de novo hearing.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~2",
          "quote": "Such an appeal is not an appeal merely to decide whether the decision of the Registrar can be supported but a complete re-decision, on the material before the court, of the entire question. The appeal is in the nature of a de novo hearing."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual states that a court appeal must be instituted within 21 days after the decision, unless the court allows further time on application.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~2",
          "quote": "An appeal to the Federal Court or Federal Circuit and Family Court of Australia (Division 2) must be instituted within 21 days after the date of the decision appealed from (or within such further time as the Court allows on application - see Manual Section 5.5)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For a Federal Court appeal, the Manual states that the notice of appeal must be served on the Registrar within five days after filing.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/5",
          "quote": "Notice of appeal must be served on the Registrar within 5 days of the day on which the notice of appeal is filed (Rule 34.24(3))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Where the Act specifies no appeal right to either court or review right in the Administrative Review Tribunal (ART), the Manual identifies review under the Administrative Decisions (Judicial Review) Act 1977 (AD(JR) Act) as the only alternative avenue.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/1~1",
          "quote": "If the Act does not specify a right of appeal to the Federal Court, the Federal Circuit and Family Court of Australia (Division 2), or the Administrative Review Tribunal (see Manual section 5.2) the only alternative avenue is under the Administrative Decisions (Judicial Review) Act (see Manual Section 5.3)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual says that a “person aggrieved” may seek AD(JR) review of a Registrar decision in either court, including where a specific appeal or ART review right also exists.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/3",
          "quote": "Therefore, in addition to any specific rights of appeal under the Trade Marks Act 1995 to the Federal Court and the Federal Circuit and Family Court of Australia (Division 2) or to a review of the decision in the ART, a “person aggrieved” by a decision of the Registrar may seek a review of that decision in the Federal Court or the Federal Circuit and Family Court of Australia (Division 2) under the AD(JR) Act."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "AD(JR) review is described in the Manual as review of legality—not a merits re-examination—including legislative procedure, procedural fairness and the availability of evidence supporting the decision.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/3",
          "quote": "A review under the AD(JR) Act, though conducted in the Federal Court or the Federal Circuit and Family Court of Australia (Division 2), is not a re-examination of the matter. It is not a review of the merits of the decision but goes, briefly and in general terms, to the compliance with procedures under the legislation, provision of procedural fairness and to the availability of evidence on which to base the decision."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual says that, on finding a Registrar decision contrary to law, the court may set it aside and remit it for lawful reconsideration rather than substitute its own decision.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/3",
          "quote": "If the court finds a decision of the Registrar is contrary to law it will not substitute its own decision but may set aside the Registrar’s decision and refer it back to the person who made the decision for reconsideration in accordance with the law"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual gives 28 days after receipt of the decision as the normal period for applying to the Federal Court for AD(JR) review.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/3",
          "quote": "The normal time for applying for review to the Federal Court under the AD(JR) Act is 28 days after receipt of the decision."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied legislation does not include the AD(JR) Act, so its eligibility requirements and any qualifications to the Manual’s account cannot be independently established from these materials.",
      "quotes": [],
      "authority": "none"
    },
    {
      "text": "The Manual identifies ART review, rather than a direct statutory court appeal, for a Registrar’s refusal of an extension under section 224 and for specified decisions dismissing an opposition or deleting material because of an inadequate statement of grounds and particulars.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/2",
          "quote": "Refusal by the Registrar to grant an extension of time under the terms of section 224. An unsuccessful applicant for an extension can seek a review of the refusal (section 224(7))."
        },
        {
          "ref": "TMM/Part52/5/5/2",
          "quote": "A decision by the Registrar to dismiss an opposition because a statement of grounds and particulars is inadequate, or to delete material from a statement of grounds and particulars (section 99A, subregs 5.8(6), 17A.34B(6))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual describes ART review as a full merits re-decision, with additional evidence admissible.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/2",
          "quote": "A review by the ART leads to a full re-decision of the matter on its merits. The tribunal stands in the shoes of the original decision maker and can exercise all of the powers open to that person. Additional evidence can be admitted."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual gives a general ART filing period of 28 days from receipt of the document setting out the decision, subject to extension.",
      "quotes": [
        {
          "ref": "TMM/Part52/5/5/2",
          "quote": "In general, the request must be filed at the ART within 28 days commencing on the date of receipt of the document setting out the decision, but the time may be extended."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For opposition decisions, the Manual’s practice is not to take further action implementing the decision once an appeal or review application has been filed, until it is decided or discontinued, subject to court or tribunal orders.",
      "quotes": [
        {
          "ref": "TMM/Part51/8#1",
          "quote": "Once an appeal or application for review has been filed no further action will be taken to implement the Registrar’s decision until the appeal/review has been decided or discontinued. The Registrar’s decision will be subject to any orders made by the court/tribunal."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Section 196 permits the Registrar to appear and be heard on an appeal against the Registrar’s decision or direction in either court.",
      "quotes": [
        {
          "ref": "TMA1995/s196",
          "quote": "The Registrar may appear and be heard at the hearing of an appeal to the Federal Court or the Federal Circuit and Family Court of Australia (Division 2) against a decision or direction of the Registrar."
        }
      ],
      "authority": "legislation"
    }
  ],
